/**
 * Sync Type Definitions
 * Matches backend SyncRecord model
 */

import type { CanonicalSyncRecord } from "@shared/contracts/item";

export interface SyncRecord extends CanonicalSyncRecord {}

export interface BatchSyncResponse {
  ok: string[];
  conflicts: {
    client_record_id: string;
    conflict_type: string;
    message: string;
    details?: Record<string, unknown>;
  }[];
  errors: {
    client_record_id: string;
    error_type: string;
    message: string;
  }[];
  batch_id?: string;
  processing_time_ms: number;
  total_records: number;
  processed_count?: number;
  success_count?: number;
  failed_count?: number;
  results?: SyncResult[];
}

export interface SyncResult {
  id: string;
  success: boolean;
  message?: string;
}

export interface SyncBatchResult extends BatchSyncResponse {
  results: SyncResult[];
}
